            Xpb98StatusResponse response = new Xpb98StatusResponse(updatedStatus);
            log.info("배송 상태 조회 완료: shipmentId={}, status={}", shipmentId, updatedStatus);

            return ResponseEntity.ok(response);

        } catch (Xpb98Exception e) {
            log.error("배송 상태 조회 실패 (Xpb98Exception): shipmentId={}, code={}, message={}",
                    shipmentId, e.getErrorCode().getCode(), e.getMessage());

