200	                Xpb98Status newStatus = mapToShipmentStatus(currentStatus);
201	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
202	
203	
204	                if (orderShipment.getStatus() == newStatus) {
